use crate::Color;

/// Light or dark, as `appearance` in theme.toml. Every theme has only its dark variant so far.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Appearance {
    Light,
    Dark,
}

/// Every colour token of one theme.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Colors {
    /// Desktop behind everything, boot splash, installer. Tinted faintly toward the god in each theme. Ground for text, text-muted, accent-text, error.
    pub background: Color,
    /// Windows, panels, the pill, cards, dialogs. Ground for text, text-muted, accent-text, error.
    pub surface: Color,
    /// Hover and selected rows, tooltips, the cover of a media card. One step above surface.
    pub surface_raised: Color,
    /// Wells: text fields, switch track, segmented track.
    pub surface_sunken: Color,
    /// Decorative lines and frames on surface and background: inactive window border, dividers, progress track.
    pub border: Color,
    /// Borders that carry meaning: controls, secondary buttons, tooltips. 3.2:1 or more on every surface.
    pub border_strong: Color,
    /// The border of the focused window: the accent quietened toward border, so focus shows without glowing. About 2:1 on background; inactive windows are dimmed as well, so focus never rests on this colour alone.
    pub border_active: Color,
    /// Cream line work: wallpaper drawing, bracket frames, the edge of the selected theme card. Drawn at 1px, usually at reduced opacity.
    pub line: Color,
    /// Dimming layer under dialogs, the session menu and the theme picker.
    pub scrim: Color,
    /// Primary text on background, surface and surface-raised (13.9:1 or more). Wordmark, slider thumb.
    pub text: Color,
    /// Secondary text and resting icons on background, surface and surface-raised (6.2:1 or more).
    pub text_muted: Color,
    /// Placeholders, line numbers, timestamps, the :: separator. 3.6:1 or more: never for text a person must read.
    pub text_faint: Color,
    /// The colour of the theme: Strix red under Saturnus, the default, and one muted hue per god. Fills only: main action, selected segment, active workspace, active window border, running progress, cursor, the disc of the wallpaper. Not for text; use accent-text.
    pub accent: Color,
    /// Primary button under the pointer.
    pub accent_hover: Color,
    /// Primary button while pressed.
    pub accent_pressed: Color,
    /// Quiet ground in the accent hue: hover of a danger button, selection in text.
    pub accent_soft: Color,
    /// The accent as text or icon on background, surface, surface-raised and accent-soft (5.2:1 or more): the list caret, the power icon, links.
    pub accent_text: Color,
    /// Text and icons on accent, accent-hover and accent-pressed (4.5:1 or more in every theme): white on dark accents, near-black on light ones.
    pub on_accent: Color,
    /// Focus ring, 2px, after a 2px gap in background. 4.0:1 or more on background, surface and surface-raised in every theme.
    pub focus: Color,
    /// Error text and the border of a field in error, on background, surface and surface-raised (6.3:1 or more). Always with words.
    pub error: Color,
    /// Warnings as text or icon with words, on background and surface (7.7:1 or more). Never a filled box.
    pub warning: Color,
    /// Success as text or icon with words, on background and surface (7.8:1 or more).
    pub success: Color,
    /// Neutral information as text or icon with words, on background and surface (7.1:1 or more).
    pub info: Color,
    /// Code: keywords and storage.
    pub syntax_keyword: Color,
    /// Code: strings.
    pub syntax_string: Color,
    /// Code: numbers and units.
    pub syntax_number: Color,
    /// Code: function names, set bold.
    pub syntax_function: Color,
    /// Code: types and modules.
    pub syntax_type: Color,
    /// Code: constants, attributes, macros.
    pub syntax_constant: Color,
    /// Code: comments, set italic. 4.6:1 or more on background and surface.
    pub syntax_comment: Color,
    /// Code: operators and punctuation.
    pub syntax_operator: Color,
    /// Charts: the series that matters. Also the peak bars of the visualizer.
    pub chart_1: Color,
    /// Charts: second series.
    pub chart_2: Color,
    /// Charts: third series, and bars at rest.
    pub chart_3: Color,
    /// Charts: fourth series.
    pub chart_4: Color,
    /// Charts: fifth series. Series differ in lightness, so they hold without colour.
    pub chart_5: Color,
}

